// ============================================================================

ordersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
